   239→}
   240→
   241→/* Glass Morphism */
   242→.glass {
   243→  background: rgba(255, 255, 255, 0.05);
   244→  backdrop-filter: blur(var(--blur-lg));
   245→  border: 1px solid rgba(255, 255, 255, 0.1);
   246→}
   247→
   248→.glass-dark {
   249→  background: rgba(0, 0, 0, 0.4);
   250→  backdrop-filter: blur(var(--blur-lg));
   251→  border: 1px solid rgba(255, 255, 255, 0.05);
   252→}
   253→
   254→/* Animations */
   255→.fade-in {
   256→  animation: fadeIn var(--duration-normal) var(--ease-out);
   257→}
   258→
   259→.slide-up {
   260→  animation: slideUp var(--duration-normal) var(--ease-out);
   261→}
   262→
   263→.slide-down {
   264→  animation: slideDown var(--duration-normal) var(--ease-out);
   265→}
   266→
   267→.slide-left {
   268→  animation: slideLeft var(--duration-normal) var(--ease-out);
   269→}
   270→
   271→.slide-right {
   272→  animation: slideRight var(--duration-normal) var(--ease-out);
   273→}
   274→
   275→@keyframes fadeIn {
   276→  from {
   277→    opacity: 0;
   278→  }
   279→  to {
   280→    opacity: 1;
   281→  }
   282→}
   283→
   284→@keyframes slideUp {
   285→  from {
   286→    transform: translateY(20px);
   287→    opacity: 0;
   288→  }
   289→  to {
   290→    transform: translateY(0);
   291→    opacity: 1;
   292→  }
   293→}
   294→
   295→@keyframes slideDown {
   296→  from {
   297→    transform: translateY(-20px);
   298→    opacity: 0;
   299→  }
   300→  to {
   301→    transform: translateY(0);
   302→    opacity: 1;
   303→  }
   304→}
   305→
   306→@keyframes slideLeft {
   307→  from {
   308→    transform: translateX(20px);
   309→    opacity: 0;
   310→  }
   311→  to {
   312→    transform: translateX(0);
   313→    opacity: 1;
   314→  }
   315→}
   316→
   317→@keyframes slideRight {
