      month: h.month,
      score: h[id]?.overallScore || 0,
    })) || [],
    components: paradigm || {},
  };
}

function getParadigmName(id: string): string {
  const names: Record<string, string> = {
    westernLiberal: 'Western Liberal',
    development: 'Development',
    ecological: 'Ecological',
    indigenous: 'Indigenous',
  };
  return names[id] || id;
}

