     3→/**
     4→ * Real-Time Simulation Dashboard - Paradigm-Focused Edition
     5→ *
     6→ * Ultra-futuristic dashboard with Multi-Paradigm DUI as centerpiece.
     7→ * Inspired by Elysium (2013) medical/systems interfaces.
     8→ * High-contrast, data-dense, clean geometry, glowing accents.
     9→ *
    10→ * Features:
    11→ * - Multi-Paradigm DUI histogram with sparklines (front & center)
    12→ * - Comprehensive economic indicators panel
    13→ * - Expanded government information with active policies
    14→ * - Real-time sparkline trends throughout
    15→ * - Color-coded severity indicators
    16→ * - Glowing effects for critical states
    17→ * - Web Worker-based non-blocking simulation
    18→ */
    19→
    20→import { useState, useEffect, useCallback, useRef } from 'react';
    21→import { SimulationWorkerClient, type StateDelta, type InitialStateSnapshot } from '@/lib/simulationWorkerClient';
    22→import { Sparkline } from '@/components/Sparkline';
    23→import type { ScenarioMode } from '@/types/game';
    24→
    25→// History tracking for sparklines
    26→interface MetricHistory {
    27→  qualityOfLife: number[];
    28→  population: number[];
    29→  aiCapability: number[];
    30→  climateChange: number[];
    31→  socialCohesion: number[];
    32→  extinctionRisk: number[];
    33→  dystopiaRisk: number[];
    34→  utopiaProgress: number[];
    35→  // Paradigm histories
    36→  westernLiberal: number[];
    37→  development: number[];
    38→  ecological: number[];
    39→  indigenous: number[];
    40→  // Economic histories
    41→  gdp: number[];
    42→  employment: number[];
    43→  inequality: number[];
    44→  inflation: number[];
    45→}
    46→
    47→// Panel component for consistent styling
    48→interface PanelProps {
    49→  title: string;
    50→  children: React.ReactNode;
    51→  className?: string;
    52→  glow?: 'cyan' | 'amber' | 'red' | 'green';
    53→}
    54→
    55→const Panel: React.FC<PanelProps> = ({ title, children, className = '', glow }) => {
    56→  const glowColors = {
    57→    cyan: 'shadow-[0_0_20px_rgba(0,240,255,0.3)]',
    58→    amber: 'shadow-[0_0_20px_rgba(255,176,0,0.3)]',
    59→    red: 'shadow-[0_0_20px_rgba(255,0,64,0.3)]',
    60→    green: 'shadow-[0_0_20px_rgba(0,255,136,0.3)]'
    61→  };
    62→
    63→  return (
    64→    <div className={`bg-black/90 border border-white/10 p-4 ${glow ? glowColors[glow] : ''} ${className}`}>
    65→      <h3 className="text-xs font-light uppercase tracking-[0.2em] text-white/40 mb-3">
    66→        {title}
    67→      </h3>
    68→      <div>{children}</div>
    69→    </div>
    70→  );
    71→};
    72→
    73→// Metric display component
    74→interface MetricProps {
    75→  label: string;
    76→  value: string | number;
    77→  unit?: string;
    78→  trend?: 'up' | 'down' | 'stable';
    79→  color?: 'green' | 'yellow' | 'red' | 'cyan' | 'white';
    80→  sparkline?: number[];
    81→  className?: string;
    82→}
    83→
    84→const Metric: React.FC<MetricProps> = ({
    85→  label,
    86→  value,
    87→  unit = '',
    88→  trend,
    89→  color = 'white',
    90→  sparkline,
    91→  className = ''
    92→}) => {
    93→  const colorMap = {
    94→    green: 'text-green-400',
    95→    yellow: 'text-yellow-400',
    96→    red: 'text-red-400',
    97→    cyan: 'text-cyan-400',
    98→    white: 'text-white'
    99→  };
   100→
   101→  const trendIcon = trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→';
   102→
   103→  return (
   104→    <div className={`${className}`}>
   105→      <div className="text-[10px] text-white/30 uppercase tracking-wider mb-1">{label}</div>
   106→      <div className="flex items-baseline gap-2">
   107→        <span className={`text-2xl font-light tabular-nums ${colorMap[color]}`}>
   108→          {value}
   109→        </span>
   110→        {unit && <span className="text-sm text-white/40">{unit}</span>}
   111→        {trend && <span className="text-sm text-white/40">{trendIcon}</span>}
   112→      </div>
   113→      {sparkline && sparkline.length > 1 && (
   114→        <div className="mt-2">
   115→          <Sparkline
   116→            data={sparkline}
   117→            width={120}
   118→            height={25}
   119→            color={color === 'green' ? '#00FF88' :
   120→                   color === 'yellow' ? '#FFB000' :
   121→                   color === 'red' ? '#FF0040' :
   122→                   color === 'cyan' ? '#00F0FF' : '#FFFFFF'}
   123→            showArea
   124→          />
   125→        </div>
   126→      )}
   127→    </div>
   128→  );
   129→};
   130→
   131→// Paradigm Time Series component - shows historical values over time
   132→interface ParadigmTimeSeriesProps {
   133→  name: string;
   134→  value: number;
   135→  color: string;
   136→  history?: number[];
   137→  trend?: 'up' | 'down' | 'stable';
   138→  allHistories?: {
   139→    westernLiberal: number[];
   140→    development: number[];
   141→    ecological: number[];
   142→    indigenous: number[];
   143→  };
   144→}
   145→
   146→const ParadigmTimeSeries: React.FC<ParadigmTimeSeriesProps> = ({ name, value, color, history, trend, allHistories }) => {
   147→  const trendIcon = trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→';
   148→  const percentage = (value * 100).toFixed(1);
   149→
   150→  // Determine status based on value
   151→  const status = value >= 0.7 ? 'OPTIMAL' : value >= 0.4 ? 'STABLE' : value >= 0.2 ? 'WARNING' : 'CRITICAL';
   152→  const statusColor = value >= 0.7 ? 'text-green-400' : value >= 0.4 ? 'text-cyan-400' : value >= 0.2 ? 'text-yellow-400' : 'text-red-400';
   153→
   154→  // Convert history to percentage values for display
   155→  const historyPercentages = (history || []).map(v => v * 100);
   156→
   157→  // Calculate min/max for better visualization
   158→  const minValue = Math.min(...(historyPercentages.length > 0 ? historyPercentages : [0]));
   159→  const maxValue = Math.max(...(historyPercentages.length > 0 ? historyPercentages : [100]));
   160→  const range = maxValue - minValue || 100;
   161→
   162→  return (
   163→    <div className="space-y-4">
   164→      {/* Header with name and current value */}
   165→      <div className="flex items-center justify-between">
   166→        <div className="flex items-center gap-3">
   167→          <span className="text-base font-light text-white/90">{name}</span>
   168→        </div>
   169→        <div className="flex items-center gap-3">
   170→          <span className={`text-xs ${statusColor} font-mono uppercase tracking-wider`}>{status}</span>
   171→          <span className="text-sm text-white/40">{trendIcon}</span>
   172→          <span className="text-2xl font-light text-white tabular-nums">{percentage}%</span>
   173→        </div>
   174→      </div>
   175→
   176→      {/* Time Series Area Chart */}
   177→      <div className="relative bg-black border border-white/20 overflow-hidden" style={{ height: '120px' }}>
   178→        {historyPercentages.length > 1 ? (
   179→          <>
   180→            {/* Chart container with proper sizing */}
   181→            <div className="w-full h-full relative">
