     1→/**
     2→ * Simulation Worker Client
     3→ *
     4→ * Main thread interface for communicating with simulation Web Worker.
     5→ * Provides a clean API for starting/stopping simulation and receiving updates.
     6→ *
     7→ * Usage:
     8→ *   const client = new SimulationWorkerClient();
     9→ *   client.on('update', (delta, month) => console.log('Month:', month));
    10→ *   client.init(42000, 'historical');
    11→ *   client.start();
    12→ */
    13→
    14→import type { ScenarioMode } from '@/types/game';
    15→
    16→// Re-export types from worker (expanded for comprehensive dashboard)
    17→export interface StateDelta {
    18→  // Core metrics
    19→  currentMonth?: number;
    20→  qualityOfLife?: number;
    21→  population?: number;
    22→  aiCount?: number;
    23→
    24→  // AI System Metrics
    25→  dystopiaProgression?: number;
    26→  avgAICapability?: number;
    27→  deployedTechCount?: number;
    28→  alignedAICount?: number;
    29→  misalignedAICount?: number;
    30→  sleeperAgentCount?: number;
    31→  aiDeploymentPhase?: 'training' | 'testing' | 'deployed' | 'open_source';
    32→
    33→  // Environmental Metrics
    34→  climateChange?: number;
    35→  resourceDepletion?: number;
    36→  biodiversityLoss?: number;
    37→  pollutionLevel?: number;
    38→  planetaryBoundariesCrossed?: number;
    39→  environmentalDebtLevel?: number;
    40→
    41→  // Social Metrics
    42→  socialCohesion?: number;
    43→  institutionalTrust?: number;
    44→  meaningLevel?: number;
    45→  socialDebtLevel?: number;
    46→
    47→  // Crisis Indicators
    48→  activeCrises?: Array<{ type: string; severity: number; duration: number }>;
    49→  phosphorusDepletion?: number;
    50→  freshwaterStress?: number;
    51→  oceanAcidification?: number;
    52→  novelEntitiesLevel?: number;
    53→
    54→  // Government & Governance
    55→  governmentAIRegulation?: number;
    56→  governmentInvestment?: number;
    57→  governmentComprehension?: number;
    58→  internationalCooperation?: number;
    59→
    60→  // Technology & Research
    61→  activeResearch?: Array<{ tech: string; progress: number }>;
    62→  deployedTechs?: Array<{ name: string; tier: number; deployment: number }>;
    63→  techRiskLevel?: number;
    64→
    65→  // Upward Spirals & Outcomes
    66→  activeSpirals?: Array<{ type: string; strength: number; duration: number }>;
    67→  utopiaProgress?: number;
    68→  extinctionProbability?: number;
    69→  outcomeType?: string;
    70→
    71→  // Multi-Paradigm DUI (4 perspectives)
    72→  westernLiberalIndex?: number;
    73→  developmentIndex?: number;
    74→  ecologicalIndex?: number;
    75→  indigenousIndex?: number;
    76→
    77→  // Events (optional - only when significant changes happen)
    78→  events?: Array<{
    79→    type: string;
    80→    description: string;
    81→    severity?: 'low' | 'medium' | 'high' | 'critical';
    82→    category?: 'ai' | 'environment' | 'social' | 'crisis' | 'tech' | 'governance';
    83→  }>;
    84→}
    85→
    86→export interface InitialStateSnapshot {
    87→  currentMonth: number;
    88→  qualityOfLife: number;
    89→  population: number;
    90→  aiCount: number;
    91→  scenario: ScenarioMode;
    92→}
    93→
    94→type EventCallback = (...args: any[]) => void;
    95→
    96→export class SimulationWorkerClient {
    97→  private worker: Worker | null = null;
    98→  private callbacks: Map<string, Set<EventCallback>> = new Map();
    99→  private initialized = false;
   100→  private running = false;
   101→
   102→  constructor() {
   103→    // Only create worker in browser environment
   104→    if (typeof window === 'undefined' || typeof Worker === 'undefined') {
   105→      console.warn('Web Workers not available (running in Node.js or unsupported browser)');
   106→      return; // Don't throw - allow SSR to work
   107→    }
   108→
   109→    try {
   110→      // Create worker from TypeScript file (Next.js handles bundling)
   111→      // Note: Using dynamic import to avoid SSR issues
   112→      this.worker = new Worker(
   113→        new URL('../workers/simulationWorker.ts', import.meta.url),
   114→        {
   115→          type: 'module',
   116→          name: 'simulation-worker'
   117→        }
   118→      );
   119→
   120→      this.worker.addEventListener('message', this.handleMessage.bind(this));
   121→      this.worker.addEventListener('error', this.handleError.bind(this));
   122→
   123→      console.log('[Client] Web Worker created successfully');
   124→    } catch (error) {
   125→      console.error('[Client] Failed to create Web Worker:', error);
   126→      this.worker = null;
   127→      // Don't throw - allow component to render with error message
   128→    }
   129→  }
   130→
   131→  private handleMessage(event: MessageEvent) {
   132→    const msg = event.data;
   133→
   134→    switch (msg.type) {
   135→      case 'initialized':
   136→        this.initialized = true;
   137→        this.emit('initialized', msg.initialState, msg.startDate);
   138→        break;
   139→
   140→      case 'update':
   141→        this.emit('update', msg.delta, msg.month, msg.day, msg.calendarDate, msg.timestamp);
   142→        break;
   143→
   144→      case 'dayUpdate':
   145→        this.emit('dayUpdate', msg.day, msg.calendarDate);
   146→        break;
   147→
   148→      case 'paused':
   149→        this.running = false;
   150→        this.emit('paused', msg.month, msg.day);
   151→        break;
   152→
   153→      case 'resumed':
   154→        this.running = true;
   155→        this.emit('resumed', msg.month, msg.day);
   156→        break;
   157→
   158→      case 'error':
   159→        this.emit('error', new Error(msg.error));
   160→        break;
   161→
   162→      default:
   163→        console.warn('Unknown message type from worker:', msg.type);
   164→    }
   165→  }
   166→
   167→  private handleError(event: ErrorEvent) {
   168→    console.error('Worker error:', event);
   169→    this.emit('error', event.error || new Error(event.message));
   170→  }
   171→
   172→  // Event emitter pattern
   173→  on(event: string, callback: EventCallback): void {
   174→    if (!this.callbacks.has(event)) {
   175→      this.callbacks.set(event, new Set());
   176→    }
   177→    this.callbacks.get(event)!.add(callback);
   178→  }
   179→
   180→  off(event: string, callback: EventCallback): void {
   181→    this.callbacks.get(event)?.delete(callback);
   182→  }
   183→
   184→  once(event: string, callback: EventCallback): void {
   185→    const wrappedCallback = (...args: any[]) => {
   186→      callback(...args);
   187→      this.off(event, wrappedCallback);
   188→    };
   189→    this.on(event, wrappedCallback);
   190→  }
   191→
   192→  private emit(event: string, ...args: any[]): void {
   193→    this.callbacks.get(event)?.forEach(cb => {
   194→      try {
   195→        cb(...args);
   196→      } catch (error) {
   197→        console.error(`Error in ${event} callback:`, error);
   198→      }
   199→    });
   200→  }
   201→
   202→  // Public API
   203→
   204→  /**
   205→   * Initialize simulation with seed and scenario
   206→   * @param seed - RNG seed for deterministic runs
   207→   * @param scenario - 'historical' or 'unprecedented'
   208→   * @param interval - Simulation step interval in milliseconds (default: 30000 = 1 month/30 seconds)
   209→   */
   210→  init(seed: number, scenario: ScenarioMode = 'historical', interval = 30000): void {
   211→    if (this.initialized) {
   212→      throw new Error('Already initialized. Create a new client to reinitialize.');
   213→    }
   214→
   215→    if (!this.worker) {
   216→      throw new Error('Worker not available. Check browser console for errors. Web Workers may not be supported in this environment.');
   217→    }
   218→
   219→    console.log('[Client] Initializing worker with seed:', seed, 'scenario:', scenario);
   220→
   221→    this.worker.postMessage({
   222→      type: 'init',
   223→      seed,
   224→      scenario,
   225→      interval
   226→    });
   227→  }
   228→
   229→  /**
   230→   * Start simulation (auto-steps at configured interval)
   231→   */
   232→  start(): void {
   233→    if (!this.initialized) {
   234→      throw new Error('Not initialized. Call init() first.');
   235→    }
   236→
   237→    if (this.running) {
   238→      console.warn('Simulation already running');
   239→      return;
   240→    }
   241→
   242→    this.worker?.postMessage({ type: 'start' });
   243→    this.running = true;
   244→  }
   245→
   246→  /**
   247→   * Pause simulation
   248→   */
   249→  pause(): void {
   250→    if (!this.running) {
   251→      console.warn('Simulation not running');
   252→      return;
   253→    }
   254→
   255→    this.worker?.postMessage({ type: 'pause' });
   256→  }
   257→
   258→  /**
   259→   * Resume simulation after pause
   260→   */
   261→  resume(): void {
   262→    if (this.running) {
   263→      console.warn('Simulation already running');
   264→      return;
   265→    }
   266→
   267→    if (!this.initialized) {
   268→      throw new Error('Not initialized. Call init() first.');
   269→    }
   270→
   271→    this.worker?.postMessage({ type: 'resume' });
   272→  }
   273→
   274→  /**
   275→   * Manually step simulation once (useful when paused)
   276→   */
   277→  step(): void {
   278→    if (!this.initialized) {
   279→      throw new Error('Not initialized. Call init() first.');
   280→    }
   281→
   282→    this.worker?.postMessage({ type: 'step' });
   283→  }
   284→
   285→  /**
   286→   * Change simulation speed
   287→   * @param interval - Step interval in milliseconds
   288→   */
   289→  setSpeed(interval: number): void {
   290→    if (!this.initialized) {
   291→      throw new Error('Not initialized. Call init() first.');
   292→    }
   293→
   294→    this.worker?.postMessage({ type: 'setSpeed', interval });
   295→  }
   296→
   297→  /**
   298→   * Inject player decision (Phase 3 - future work)
   299→   * @param decision - Player decision to inject
   300→   */
   301→  decision(decision: any): void {
   302→    if (!this.initialized) {
   303→      throw new Error('Not initialized. Call init() first.');
   304→    }
   305→
   306→    this.worker?.postMessage({ type: 'decision', decision });
   307→  }
   308→
   309→  /**
   310→   * Terminate worker and clean up
   311→   */
   312→  destroy(): void {
   313→    if (this.worker) {
   314→      this.worker.terminate();
   315→      this.worker = null;
   316→    }
   317→    this.callbacks.clear();
   318→    this.initialized = false;
   319→    this.running = false;
   320→  }
   321→
   322→  // Getters
   323→  isInitialized(): boolean {
   324→    return this.initialized;
   325→  }
   326→
   327→  isRunning(): boolean {
   328→    return this.running;
   329→  }
   330→}
   331→
   332→// Helper hook for React (optional)
   333→export function useSimulationWorker() {
   334→  if (typeof window === 'undefined') {
   335→    return null; // SSR guard
   336→  }
   337→
   338→  // Client-side only
   339→  return new SimulationWorkerClient();
   340→}
