   434→function startSimulationLoop() {
   435→  // Clear any existing intervals
   436→  if (simulationIntervalId !== null) {
   437→    clearInterval(simulationIntervalId);
   438→  }
   439→  if (dayIntervalId !== null) {
   440→    clearInterval(dayIntervalId);
   441→  }
   442→
   443→  // Don't reset currentDay here - it should only reset when the month actually advances
   444→  // On initialization, currentDay is set to the actual date (e.g., 22)
   445→  // When month advances in performStep(), it will be reset to 1 there
   446→
   447→  // Calculate days in current month (approximate to 30 for now)
   448→  const daysInMonth = 30;
   449→
   450→  // Start day counter (updates every second)
   451→  dayIntervalId = setInterval(() => {
   452→    if (!running || !startDate) {
   453→      if (dayIntervalId !== null) {
   454→        clearInterval(dayIntervalId);
   455→        dayIntervalId = null;
   456→      }
   457→      return;
   458→    }
   459→
   460→    // Increment day continuously (no cap - it's OK if day 31+ appears)
   461→    currentDay++;
   462→
   463→    // Calculate actual calendar date: startDate + elapsed days
   464→    const monthsElapsed = state?.currentMonth || 0;
   465→    const totalDaysElapsed = (monthsElapsed * 30) + (currentDay - 1);
   466→    const calendarDate = new Date(startDate);
   467→    calendarDate.setDate(calendarDate.getDate() + totalDaysElapsed);
   468→
   469→    // Send day update to UI
   470→    self.postMessage({
   471→      type: 'dayUpdate',
   472→      day: currentDay,
   473→      calendarDate: calendarDate.toISOString()
   474→    } as WorkerResponse);
   475→  }, 1000); // Update every second
   476→
   477→  // Start simulation step interval (runs actual simulation)
   478→  simulationIntervalId = setInterval(() => {
   479→    if (!running || !engine || !state) {
   480→      if (simulationIntervalId !== null) {
   481→        clearInterval(simulationIntervalId);
   482→        simulationIntervalId = null;
   483→      }
   484→      return;
   485→    }
   486→
   487→    // Reset day to 1 for new month
   488→    currentDay = 1;
   489→
   490→    // Perform simulation step
   491→    performStep();
   492→  }, stepInterval); // Default 30 seconds = 1 month
   493→}
   494→
   495→function performStep() {
   496→  if (!engine || !state || !previousState) {
   497→    return;
   498→  }
   499→
   500→  // Run one simulation step (mutates state in place)
   501→  engine.step(state);
   502→
   503→  // Calculate delta (only changed fields, or all fields on first step)
   504→  const delta = calculateDelta(previousState, state);
   505→
   506→  // Reset first step flag after sending full delta
   507→  if (isFirstStep) {
   508→    isFirstStep = false;
   509→  }
   510→
   511→  // Update previous state snapshot
   512→  previousState = captureStateSnapshot(state);
   513→
   514→  // Calculate calendar date: startDate + elapsed days
   515→  const monthsElapsed = state.currentMonth;
   516→  const totalDaysElapsed = (monthsElapsed * 30) + (currentDay - 1);
   517→  const calendarDate = new Date(startDate!);
   518→  calendarDate.setDate(calendarDate.getDate() + totalDaysElapsed);
   519→
   520→  // Send update to main thread
   521→  self.postMessage({
   522→    type: 'update',
   523→    delta,
   524→    month: state.currentMonth,
   525→    day: currentDay,
   526→    calendarDate: calendarDate.toISOString(),
   527→    timestamp: Date.now()
   528→  } as WorkerResponse);
   529→}
   530→
   531→function captureStateSnapshot(state: GameState): StateSnapshot {
   532→  // Capture only fields we need for delta calculation
   533→  // Don't deep clone entire 1.78MB state (too expensive)
   534→
   535→  // Calculate AI metrics
   536→  const avgAICapability = state.aiAgents.length > 0
   537→    ? state.aiAgents.reduce((sum, ai) => sum + (ai.capability || 0), 0) / state.aiAgents.length
   538→    : 0;
   539→
   540→  // Alignment is a number [0,1], where >= 0.5 is aligned
   541→  const alignedAICount = state.aiAgents.filter(ai => ai.alignment >= 0.5).length;
   542→  const misalignedAICount = state.aiAgents.filter(ai => ai.alignment < 0.5).length;
   543→  const sleeperAgentCount = state.aiAgents.filter(ai => ai.sleeperAgent).length;
   544→
   545→  // Environmental metrics
   546→  // Climate: temperatureAnomaly in °C, normalize to [0,1] where 1 = 4°C (catastrophic)
   547→  const climateChange = Math.min(1, (state.resourceEconomy?.co2?.temperatureAnomaly || 0) / 4);
   548→  const resourceDepletion = state.resourceEconomy?.totalResourceSecurity || 1.0; // [0,1] Overall resource availability
   549→  // Note: populationPercentage is stored as 60 (meaning 60%), need to normalize to 0.6 for formatPercent() in UI
   550→  const biodiversityLoss = (state.specificTippingPoints?.pollinators?.populationPercentage || 100) / 100;
   551→  // Pollution from novel entities system (PFAS, microplastics, etc.)
   552→  const pollutionLevel = state.novelEntitiesSystem?.syntheticChemicalLoad || 0;
   553→  const environmentalDebtLevel = state.environmentalAccumulation?.pollutionLevel || 0;
   554→
   555→  // Count planetary boundaries crossed (using correct boundary names from types)
   556→  let planetaryBoundariesCrossed = 0;
   557→  if (state.planetaryBoundariesSystem?.boundaries) {
   558→    const boundaries = state.planetaryBoundariesSystem.boundaries;
   559→    const isCrossed = (status: string) =>
   560→      status === 'beyond_boundary' || status === 'increasing_risk' || status === 'high_risk';
   561→
   562→    // Correct boundary names from BoundaryName type definition
   563→    if (boundaries.climate_change && isCrossed(boundaries.climate_change.status)) planetaryBoundariesCrossed++;
   564→    if (boundaries.biosphere_integrity && isCrossed(boundaries.biosphere_integrity.status)) planetaryBoundariesCrossed++;
   565→    if (boundaries.land_system_change && isCrossed(boundaries.land_system_change.status)) planetaryBoundariesCrossed++;
   566→    if (boundaries.freshwater_change && isCrossed(boundaries.freshwater_change.status)) planetaryBoundariesCrossed++;
   567→    if (boundaries.biogeochemical_flows && isCrossed(boundaries.biogeochemical_flows.status)) planetaryBoundariesCrossed++;
   568→    if (boundaries.novel_entities && isCrossed(boundaries.novel_entities.status)) planetaryBoundariesCrossed++;
   569→    if (boundaries.ocean_acidification && isCrossed(boundaries.ocean_acidification.status)) planetaryBoundariesCrossed++;
   570→    if (boundaries.stratospheric_ozone && isCrossed(boundaries.stratospheric_ozone.status)) planetaryBoundariesCrossed++;
   571→    if (boundaries.atmospheric_aerosols && isCrossed(boundaries.atmospheric_aerosols.status)) planetaryBoundariesCrossed++;
   572→  }
   573→
   574→  // Social metrics
   575→  const socialCohesion = state.socialAccumulation?.socialCohesion || 1.0;
   576→  const institutionalTrust = state.socialAccumulation?.institutionalLegitimacy || 1.0;
   577→  const meaningLevel = state.socialAccumulation?.meaningAlignment || 1.0;
   578→  const socialDebtLevel = state.socialAccumulation?.totalDebt || 0;
   579→
   580→  // Crisis metrics
   581→  const phosphorusDepletion = 1 - (state.phosphorusSystem?.reserves || 1);
   582→  const freshwaterStress = state.freshwaterSystem?.waterStress || 0;
   583→  const oceanAcidification = 1 - (state.oceanAcidificationSystem?.pHLevel || 1);
   584→  const novelEntitiesLevel = state.novelEntitiesSystem?.syntheticChemicalLoad || 0;
   585→
   586→  // Count active crises
   587→  let activeCrisesCount = 0;
   588→  if (state.phosphorusSystem?.criticalDepletionActive || state.phosphorusSystem?.supplyShockActive) activeCrisesCount++;
   589→  if (state.freshwaterSystem?.criticalScarcityActive || state.freshwaterSystem?.dayZeroDrought?.active) activeCrisesCount++;
   590→  if (state.oceanAcidificationSystem?.coralExtinctionActive || state.oceanAcidificationSystem?.boundaryBreached) activeCrisesCount++;
   591→  if (state.novelEntitiesSystem?.reproductiveCrisisActive || state.novelEntitiesSystem?.boundaryBreached) activeCrisesCount++;
   592→
   593→  // Government metrics
   594→  const governmentAIRegulation = state.government.capabilityToControl || 0; // [0,∞) Actual regulatory effectiveness
   595→  const governmentInvestment = state.government.alignmentResearchInvestment || 0; // [0,10]
   596→  const governmentComprehension = (state.government.oversightLevel || 0) / 10; // Normalize [0,10] to [0,1]
   597→  const internationalCooperation = state.government.structuralChoices?.internationalCoordination ? 1 : 0;
   598→
   599→  // Technology metrics
   600→  // Count deployed techs across all regions
   601→  let deployedTechCount = 0;
   602→  if (state.techTreeState?.regionalDeployment) {
   603→    const deployedTechIds = new Set<string>();
   604→    Object.values(state.techTreeState.regionalDeployment).forEach(regionDeployments => {
   605→      regionDeployments?.forEach(deployment => {
   606→        if (deployment.deploymentLevel > 0) {
   607→          deployedTechIds.add(deployment.techId);
   608→        }
   609→      });
   610→    });
   611→    deployedTechCount = deployedTechIds.size;
   612→  }
   613→  const techRiskLevel = state.technologicalRisk?.totalRisk || 0;
   614→
   615→  // Upward spiral metrics
   616→  const activeSpiralCount = state.upwardSpirals ?
   617→    Object.values(state.upwardSpirals).filter((spiral: any) => spiral.active).length : 0;
   618→  // Calculate utopia progress from cascade mechanics (4+ spirals = cascade active)
   619→  const utopiaProgress = state.upwardSpirals?.cascadeActive ?
   620→    (state.upwardSpirals.cascadeStrength || 0) / 2 : // Normalize cascadeStrength (1-2+) to [0,1]
   621→    activeSpiralCount / 6; // Progress based on active spirals (6 total)
   622→
   623→  // Outcome metrics
   624→  const extinctionProbability = state.outcomeMetrics?.extinctionProbability || 0;
   625→
   626→  // Multi-Paradigm DUI - normalized to [0,1] from [0,100]
   627→  const westernLiberalIndex = (state.multiParadigmDUI?.paradigmScores?.western?.value || 0) / 100;
   628→  const developmentIndex = (state.multiParadigmDUI?.paradigmScores?.development?.value || 0) / 100;
   629→  const ecologicalIndex = (state.multiParadigmDUI?.paradigmScores?.ecological?.value || 0) / 100;
   630→  const indigenousIndex = (state.multiParadigmDUI?.diagnosticLenses?.indigenous?.value || 0) / 100;
   631→
   632→  return {
   633→    currentMonth: state.currentMonth,
   634→    qualityOfLife: state.globalMetrics.qualityOfLife,
   635→    population: state.humanPopulationSystem.population,
   636→    aiCount: state.aiAgents.length,
   637→    dystopiaProgression: state.globalMetrics.dystopiaProgression,
   638→    avgAICapability,
   639→    deployedTechCount,
   640→    alignedAICount,
   641→    misalignedAICount,
   642→    sleeperAgentCount,
   643→    climateChange,
   644→    resourceDepletion,
   645→    biodiversityLoss,
   646→    pollutionLevel,
   647→    planetaryBoundariesCrossed,
   648→    environmentalDebtLevel,
   649→    landUseData: state.planetaryBoundariesSystem?.landUse || null,
   650→    socialCohesion,
   651→    institutionalTrust,
   652→    meaningLevel,
   653→    socialDebtLevel,
   654→    activeCrisesCount,
   655→    phosphorusDepletion,
   656→    freshwaterStress,
   657→    oceanAcidification,
   658→    novelEntitiesLevel,
   659→    governmentAIRegulation,
   660→    governmentInvestment,
   661→    governmentComprehension,
   662→    internationalCooperation,
   663→    techRiskLevel,
   664→    activeSpiralCount,
   665→    utopiaProgress,
   666→    extinctionProbability,
   667→    westernLiberalIndex,
   668→    developmentIndex,
   669→    ecologicalIndex,
   670→    indigenousIndex
   671→  };
   672→}
   673→
   674→function calculateDelta(previous: StateSnapshot, current: GameState, forceFull = false): StateDelta {
   675→  const delta: StateDelta = {};
   676→
   677→  // Capture current state snapshot for comparison
   678→  const currentSnapshot = captureStateSnapshot(current);
   679→
   680→  // On first step or when forced, send all metrics regardless of change
   681→  if (isFirstStep || forceFull) {
   682→    return { ...currentSnapshot } as StateDelta;
   683→  }
   684→
   685→  // Core metrics - always include month
   686→  if (previous.currentMonth !== currentSnapshot.currentMonth) {
   687→    delta.currentMonth = currentSnapshot.currentMonth;
   688→  }
   689→
   690→  // Quality of Life
   691→  if (Math.abs(previous.qualityOfLife - currentSnapshot.qualityOfLife) > 0.001) {
   692→    delta.qualityOfLife = currentSnapshot.qualityOfLife;
   693→  }
   694→
   695→  // Population (stored in billions, so 0.001 = 1 million people)
   696→  if (Math.abs(previous.population - currentSnapshot.population) > 0.001) {
   697→    delta.population = currentSnapshot.population;
   698→  }
   699→
   700→  // AI System Metrics
   701→  if (previous.aiCount !== currentSnapshot.aiCount) {
   702→    delta.aiCount = currentSnapshot.aiCount;
   703→  }
   704→  if (Math.abs(previous.avgAICapability - currentSnapshot.avgAICapability) > 0.01) {
   705→    delta.avgAICapability = currentSnapshot.avgAICapability;
   706→  }
   707→  if (previous.alignedAICount !== currentSnapshot.alignedAICount) {
   708→    delta.alignedAICount = currentSnapshot.alignedAICount;
   709→  }
   710→  if (previous.misalignedAICount !== currentSnapshot.misalignedAICount) {
   711→    delta.misalignedAICount = currentSnapshot.misalignedAICount;
   712→  }
   713→  if (previous.sleeperAgentCount !== currentSnapshot.sleeperAgentCount) {
   714→    delta.sleeperAgentCount = currentSnapshot.sleeperAgentCount;
   715→  }
   716→
   717→  // Environmental Metrics
   718→  if (Math.abs(previous.climateChange - currentSnapshot.climateChange) > 0.01) {
   719→    delta.climateChange = currentSnapshot.climateChange;
   720→  }
   721→  if (Math.abs(previous.resourceDepletion - currentSnapshot.resourceDepletion) > 0.01) {
   722→    delta.resourceDepletion = currentSnapshot.resourceDepletion;
   723→  }
   724→  if (Math.abs(previous.biodiversityLoss - currentSnapshot.biodiversityLoss) > 0.01) {
   725→    delta.biodiversityLoss = currentSnapshot.biodiversityLoss;
   726→  }
   727→  if (Math.abs(previous.pollutionLevel - currentSnapshot.pollutionLevel) > 0.01) {
   728→    delta.pollutionLevel = currentSnapshot.pollutionLevel;
   729→  }
   730→  if (previous.planetaryBoundariesCrossed !== currentSnapshot.planetaryBoundariesCrossed) {
   731→    delta.planetaryBoundariesCrossed = currentSnapshot.planetaryBoundariesCrossed;
   732→  }
   733→  if (Math.abs(previous.environmentalDebtLevel - currentSnapshot.environmentalDebtLevel) > 0.01) {
   734→    delta.environmentalDebtLevel = currentSnapshot.environmentalDebtLevel;
   735→  }
   736→
   737→  // Social Metrics
   738→  if (Math.abs(previous.socialCohesion - currentSnapshot.socialCohesion) > 0.01) {
   739→    delta.socialCohesion = currentSnapshot.socialCohesion;
   740→  }
   741→  if (Math.abs(previous.institutionalTrust - currentSnapshot.institutionalTrust) > 0.01) {
   742→    delta.institutionalTrust = currentSnapshot.institutionalTrust;
   743→  }
   744→  if (Math.abs(previous.meaningLevel - currentSnapshot.meaningLevel) > 0.01) {
   745→    delta.meaningLevel = currentSnapshot.meaningLevel;
   746→  }
   747→  if (Math.abs(previous.socialDebtLevel - currentSnapshot.socialDebtLevel) > 0.01) {
   748→    delta.socialDebtLevel = currentSnapshot.socialDebtLevel;
   749→  }
   750→
   751→  // Crisis Indicators
   752→  if (previous.phosphorusDepletion !== currentSnapshot.phosphorusDepletion) {
   753→    delta.phosphorusDepletion = currentSnapshot.phosphorusDepletion;
   754→  }
   755→  if (previous.freshwaterStress !== currentSnapshot.freshwaterStress) {
   756→    delta.freshwaterStress = currentSnapshot.freshwaterStress;
   757→  }
   758→  if (Math.abs(previous.oceanAcidification - currentSnapshot.oceanAcidification) > 0.01) {
   759→    delta.oceanAcidification = currentSnapshot.oceanAcidification;
   760→  }
   761→  if (previous.novelEntitiesLevel !== currentSnapshot.novelEntitiesLevel) {
   762→    delta.novelEntitiesLevel = currentSnapshot.novelEntitiesLevel;
   763→  }
   764→
   765→  // Build active crises array if count changed
   766→  if (previous.activeCrisesCount !== currentSnapshot.activeCrisesCount) {
   767→    const activeCrises = [];
   768→    if (current.phosphorusSystem?.criticalDepletionActive || current.phosphorusSystem?.supplyShockActive) {
   769→      activeCrises.push({
   770→        type: 'Phosphorus',
   771→        severity: 1 - (current.phosphorusSystem.reserves || 1),
   772→        duration: current.phosphorusSystem.supplyShockDuration || 0
   773→      });
   774→    }
   775→    if (current.freshwaterSystem?.criticalScarcityActive || current.freshwaterSystem?.dayZeroDrought?.active) {
   776→      activeCrises.push({
   777→        type: 'Freshwater',
   778→        severity: current.freshwaterSystem.waterStress || 0,
   779→        duration: current.freshwaterSystem.dayZeroDrought?.duration || 0
   780→      });
   781→    }
   782→    if (current.oceanAcidificationSystem?.coralExtinctionActive || current.oceanAcidificationSystem?.boundaryBreached) {
   783→      activeCrises.push({
   784→        type: 'Ocean Acidification',
   785→        severity: 1 - (current.oceanAcidificationSystem.pHLevel || 1),
   786→        duration: 0 // Duration not tracked in current structure
   787→      });
   788→    }
   789→    if (current.novelEntitiesSystem?.reproductiveCrisisActive || current.novelEntitiesSystem?.boundaryBreached) {
   790→      activeCrises.push({
   791→        type: 'Chemical Pollution',
   792→        severity: current.novelEntitiesSystem.syntheticChemicalLoad || 0,
   793→        duration: 0 // Duration not tracked in current structure
   794→      });
   795→    }
   796→    delta.activeCrises = activeCrises;
   797→  }
   798→
   799→  // Government Metrics
   800→  if (Math.abs(previous.governmentAIRegulation - currentSnapshot.governmentAIRegulation) > 0.01) {
   801→    delta.governmentAIRegulation = currentSnapshot.governmentAIRegulation;
   802→  }
   803→  if (Math.abs(previous.governmentInvestment - currentSnapshot.governmentInvestment) > 1000000) {
   804→    delta.governmentInvestment = currentSnapshot.governmentInvestment;
   805→  }
   806→  if (Math.abs(previous.governmentComprehension - currentSnapshot.governmentComprehension) > 0.01) {
   807→    delta.governmentComprehension = currentSnapshot.governmentComprehension;
   808→  }
   809→  if (Math.abs(previous.internationalCooperation - currentSnapshot.internationalCooperation) > 0.01) {
   810→    delta.internationalCooperation = currentSnapshot.internationalCooperation;
   811→  }
   812→
   813→  // Technology
   814→  if (previous.deployedTechCount !== currentSnapshot.deployedTechCount) {
   815→    delta.deployedTechCount = currentSnapshot.deployedTechCount;
   816→  }
   817→  if (Math.abs(previous.techRiskLevel - currentSnapshot.techRiskLevel) > 0.01) {
   818→    delta.techRiskLevel = currentSnapshot.techRiskLevel;
   819→  }
   820→
   821→  // Dystopia progression
   822→  if (Math.abs(previous.dystopiaProgression - currentSnapshot.dystopiaProgression) > 0.01) {
   823→    delta.dystopiaProgression = currentSnapshot.dystopiaProgression;
   824→  }
   825→
   826→  // Upward Spirals & Outcomes
   827→  if (previous.activeSpiralCount !== currentSnapshot.activeSpiralCount && current.upwardSpirals) {
   828→    const activeSpirals = [];
   829→    const spirals = current.upwardSpirals as any;
   830→    if (spirals.abundanceSpiral?.active) {
   831→      activeSpirals.push({
   832→        type: 'Abundance',
   833→        strength: spirals.abundanceSpiral.strength || 0,
   834→        duration: spirals.abundanceSpiral.monthsActive || 0
   835→      });
   836→    }
   837→    if (spirals.cognitiveSpiral?.active) {
   838→      activeSpirals.push({
   839→        type: 'Cognitive',
   840→        strength: spirals.cognitiveSpiral.strength || 0,
   841→        duration: spirals.cognitiveSpiral.monthsActive || 0
   842→      });
   843→    }
   844→    if (spirals.democraticSpiral?.active) {
   845→      activeSpirals.push({
   846→        type: 'Democratic',
   847→        strength: spirals.democraticSpiral.strength || 0,
   848→        duration: spirals.democraticSpiral.monthsActive || 0
   849→      });
   850→    }
   851→    if (spirals.scientificSpiral?.active) {
   852→      activeSpirals.push({
   853→        type: 'Scientific',
   854→        strength: spirals.scientificSpiral.strength || 0,
   855→        duration: spirals.scientificSpiral.monthsActive || 0
   856→      });
   857→    }
   858→    if (spirals.meaningSpiral?.active) {
   859→      activeSpirals.push({
   860→        type: 'Meaning',
   861→        strength: spirals.meaningSpiral.strength || 0,
   862→        duration: spirals.meaningSpiral.monthsActive || 0
   863→      });
   864→    }
   865→    if (spirals.ecologicalSpiral?.active) {
   866→      activeSpirals.push({
   867→        type: 'Ecological',
   868→        strength: spirals.ecologicalSpiral.strength || 0,
   869→        duration: spirals.ecologicalSpiral.monthsActive || 0
   870→      });
   871→    }
   872→    delta.activeSpirals = activeSpirals;
   873→  }
   874→
   875→  if (Math.abs(previous.utopiaProgress - currentSnapshot.utopiaProgress) > 0.01) {
   876→    delta.utopiaProgress = currentSnapshot.utopiaProgress;
   877→  }
   878→  if (Math.abs(previous.extinctionProbability - currentSnapshot.extinctionProbability) > 0.01) {
   879→    delta.extinctionProbability = currentSnapshot.extinctionProbability;
   880→  }
   881→
   882→  // Multi-Paradigm DUI
   883→  if (Math.abs(previous.westernLiberalIndex - currentSnapshot.westernLiberalIndex) > 0.01) {
   884→    delta.westernLiberalIndex = currentSnapshot.westernLiberalIndex;
   885→  }
   886→  if (Math.abs(previous.developmentIndex - currentSnapshot.developmentIndex) > 0.01) {
   887→    delta.developmentIndex = currentSnapshot.developmentIndex;
   888→  }
   889→  if (Math.abs(previous.ecologicalIndex - currentSnapshot.ecologicalIndex) > 0.01) {
   890→    delta.ecologicalIndex = currentSnapshot.ecologicalIndex;
   891→  }
   892→  if (Math.abs(previous.indigenousIndex - currentSnapshot.indigenousIndex) > 0.01) {
   893→    delta.indigenousIndex = currentSnapshot.indigenousIndex;
   894→  }
   895→
   896→  // Determine outcome type
   897→  if (current.outcomeMetrics) {
   898→    delta.outcomeType = current.outcomeMetrics.finalOutcome || 'In Progress';
   899→  }
   900→
   901→  return delta;
   902→}
   903→
   904→// Export type for use in main thread
   905→export type { WorkerMessage, WorkerResponse, StateDelta };
