   145→
   146→const ParadigmTimeSeries: React.FC<ParadigmTimeSeriesProps> = ({ name, value, color, history, trend, allHistories }) => {
   147→  const trendIcon = trend === 'up' ? '↗' : trend === 'down' ? '↘' : '→';
   148→  const percentage = (value * 100).toFixed(1);
   149→
   150→  // Determine status based on value
   151→  const status = value >= 0.7 ? 'OPTIMAL' : value >= 0.4 ? 'STABLE' : value >= 0.2 ? 'WARNING' : 'CRITICAL';
   152→  const statusColor = value >= 0.7 ? 'text-green-400' : value >= 0.4 ? 'text-cyan-400' : value >= 0.2 ? 'text-yellow-400' : 'text-red-400';
   153→
   154→  // Convert history to percentage values for display
   155→  const historyPercentages = (history || []).map(v => v * 100);
   156→
   157→  // Calculate min/max for better visualization
   158→  const minValue = Math.min(...(historyPercentages.length > 0 ? historyPercentages : [0]));
   159→  const maxValue = Math.max(...(historyPercentages.length > 0 ? historyPercentages : [100]));
   160→  const range = maxValue - minValue || 100;
   161→
   162→  return (
   163→    <div className="space-y-4">
   164→      {/* Header with name and current value */}
   165→      <div className="flex items-center justify-between">
