   171→          <span className="text-sm text-white/40">{trendIcon}</span>
   172→          <span className="text-2xl font-light text-white tabular-nums">{percentage}%</span>
   173→        </div>
   174→      </div>
   175→
   176→      {/* Time Series Area Chart */}
   177→      <div className="relative bg-black border border-white/20 overflow-hidden" style={{ height: '120px' }}>
   178→        {historyPercentages.length > 1 ? (
   179→          <>
   180→            {/* Chart container with proper sizing */}
   181→            <div className="w-full h-full relative">
   182→              {/* Reference lines at 20%, 40%, 70% thresholds */}
   183→              <div className="absolute inset-0 pointer-events-none px-2">
   184→                {/* 70% threshold - optimal */}
   185→                <div
   186→                  className="absolute w-full border-t border-green-400/20"
   187→                  style={{ top: `${100 - ((70 - minValue) / range * 100)}%` }}
   188→                >
   189→                  <span className="absolute -top-2 right-0 text-[9px] text-green-400/40">70%</span>
   190→                </div>
   191→                {/* 40% threshold - stable */}
   192→                <div
   193→                  className="absolute w-full border-t border-cyan-400/20"
   194→                  style={{ top: `${100 - ((40 - minValue) / range * 100)}%` }}
   195→                >
   196→                  <span className="absolute -top-2 right-0 text-[9px] text-cyan-400/40">40%</span>
   197→                </div>
   198→                {/* 20% threshold - warning */}
   199→                <div
   200→                  className="absolute w-full border-t border-yellow-400/20"
   201→                  style={{ top: `${100 - ((20 - minValue) / range * 100)}%` }}
   202→                >
   203→                  <span className="absolute -top-2 right-0 text-[9px] text-yellow-400/40">20%</span>
   204→                </div>
   205→              </div>
   206→
   207→              {/* Main sparkline with area fill - constrained to container */}
   208→              <div className="absolute inset-0 p-1">
   209→                <Sparkline
   210→                  data={historyPercentages}
   211→                  width={280}
   212→                  height={114}
   213→                  color={color}
   214→                  showArea
   215→                  strokeWidth={2}
   216→                  className="mx-auto"
   217→                />
   218→              </div>
   219→            </div>
   220→
   221→            {/* Time labels */}
   222→            <div className="absolute bottom-0 left-0 right-0 flex justify-between text-[9px] text-white/30">
   223→              <span>-{historyPercentages.length}mo</span>
   224→              <span>-{Math.floor(historyPercentages.length / 2)}mo</span>
   225→              <span>now</span>
   226→            </div>
   227→          </>
   228→        ) : (
   229→          <div className="h-full flex items-center justify-center">
   230→            <div className="text-white/20 text-sm">Collecting historical data...</div>
   231→          </div>
   232→        )}
   233→      </div>
   234→
   235→      {/* Status box with insight */}
   236→      <div className="p-2 rounded bg-white/5 border border-white/10">
   237→        <div className="flex items-center justify-between">
   238→          <div className="text-xs text-white/40">
   239→            {historyPercentages.length > 10 && (
   240→              <>
   241→                {/* Show average over last 10 months */}
   242→                <span>10mo avg: {(historyPercentages.slice(-10).reduce((a, b) => a + b, 0) / 10).toFixed(1)}%</span>
   243→              </>
   244→            )}
   245→          </div>
   246→          <div className="flex items-center gap-2">
   247→            <span className="text-xs text-white/40">Current:</span>
   248→            <span className={`text-sm font-medium ${statusColor}`}>{percentage}%</span>
   249→          </div>
   250→        </div>
   251→      </div>
   252→    </div>
   253→  );
   254→};
