   583→  const institutionalTrust = state.socialAccumulation?.institutionalLegitimacy || 1.0;
   584→  const meaningLevel = state.socialAccumulation?.meaningAlignment || 1.0;
   585→  const socialDebtLevel = state.socialAccumulation?.totalDebt || 0;
   586→
   587→  // Crisis metrics
   588→  const phosphorusDepletion = 1 - (state.phosphorusSystem?.reserves || 1);
   589→  const freshwaterStress = state.freshwaterSystem?.waterStress || 0;
   590→  const oceanAcidification = 1 - (state.oceanAcidificationSystem?.pHLevel || 1);
   591→  const novelEntitiesLevel = state.novelEntitiesSystem?.syntheticChemicalLoad || 0;
   592→
   593→  // Count active crises
   594→  let activeCrisesCount = 0;
   595→  if (state.phosphorusSystem?.criticalDepletionActive || state.phosphorusSystem?.supplyShockActive) activeCrisesCount++;
   596→  if (state.freshwaterSystem?.criticalScarcityActive || state.freshwaterSystem?.dayZeroDrought?.active) activeCrisesCount++;
   597→  if (state.oceanAcidificationSystem?.coralExtinctionActive || state.oceanAcidificationSystem?.boundaryBreached) activeCrisesCount++;
   598→  if (state.novelEntitiesSystem?.reproductiveCrisisActive || state.novelEntitiesSystem?.boundaryBreached) activeCrisesCount++;
   599→
   600→  // Government metrics
   601→  const governmentAIRegulation = state.government.capabilityToControl || 0; // [0,∞) Actual regulatory effectiveness
   602→  const governmentInvestment = state.government.alignmentResearchInvestment || 0; // [0,10]
   603→  const governmentComprehension = (state.government.oversightLevel || 0) / 10; // Normalize [0,10] to [0,1]
   604→  const internationalCooperation = state.government.structuralChoices?.internationalCoordination ? 1 : 0;
   605→
   606→  // Technology metrics
   607→  // Count deployed techs across all regions
   608→  let deployedTechCount = 0;
   609→  if (state.techTreeState?.regionalDeployment) {
   610→    const deployedTechIds = new Set<string>();
   611→    Object.values(state.techTreeState.regionalDeployment).forEach(regionDeployments => {
   612→      regionDeployments?.forEach(deployment => {
   613→        if (deployment.deploymentLevel > 0) {
   614→          deployedTechIds.add(deployment.techId);
   615→        }
   616→      });
   617→    });
   618→    deployedTechCount = deployedTechIds.size;
   619→  }
   620→  const techRiskLevel = state.technologicalRisk?.totalRisk || 0;
   621→
   622→  // Upward spiral metrics
   623→  const activeSpiralCount = state.upwardSpirals ?
