   625→  // Calculate utopia progress from cascade mechanics (4+ spirals = cascade active)
   626→  const utopiaProgress = state.upwardSpirals?.cascadeActive ?
   627→    (state.upwardSpirals.cascadeStrength || 0) / 2 : // Normalize cascadeStrength (1-2+) to [0,1]
   628→    activeSpiralCount / 6; // Progress based on active spirals (6 total)
   629→
   630→  // Outcome metrics
   631→  const extinctionProbability = state.outcomeMetrics?.extinctionProbability || 0;
   632→
   633→  // Multi-Paradigm DUI - normalized to [0,1] from [0,100]
   634→  const westernLiberalIndex = (state.multiParadigmDUI?.paradigmScores?.western?.value || 0) / 100;
   635→  const developmentIndex = (state.multiParadigmDUI?.paradigmScores?.development?.value || 0) / 100;
   636→  const ecologicalIndex = (state.multiParadigmDUI?.paradigmScores?.ecological?.value || 0) / 100;
   637→  const indigenousIndex = (state.multiParadigmDUI?.diagnosticLenses?.indigenous?.value || 0) / 100;
   638→
   639→  return {
   640→    currentMonth: state.currentMonth,
   641→    qualityOfLife: state.globalMetrics.qualityOfLife,
   642→    population: state.humanPopulationSystem.population,
   643→    aiCount: state.aiAgents.length,
   644→    dystopiaProgression: state.globalMetrics.dystopiaProgression,
   645→    avgAICapability,
   646→    deployedTechCount,
   647→    alignedAICount,
   648→    misalignedAICount,
   649→    sleeperAgentCount,
   650→    climateChange,
   651→    resourceDepletion,
   652→    biodiversityLoss,
   653→    pollutionLevel,
   654→    planetaryBoundariesCrossed,
   655→    environmentalDebtLevel,
   656→    landUseData: state.planetaryBoundariesSystem?.landUse || null,
   657→    socialCohesion,
   658→    institutionalTrust,
   659→    meaningLevel,
   660→    socialDebtLevel,
   661→    activeCrisesCount,
   662→    phosphorusDepletion,
   663→    freshwaterStress,
   664→    oceanAcidification,
   665→    novelEntitiesLevel,
   666→    governmentAIRegulation,
   667→    governmentInvestment,
   668→    governmentComprehension,
   669→    internationalCooperation,
   670→    techRiskLevel,
   671→    activeSpiralCount,
   672→    utopiaProgress,
   673→    extinctionProbability,
   674→    westernLiberalIndex,
   675→    developmentIndex,
   676→    ecologicalIndex,
   677→    indigenousIndex
   678→  };
   679→}
