    36→// ============================================================================
    37→// MAIN UPDATE FUNCTION
    38→// ============================================================================
    39→
    40→export function updateResourceEconomy(state: GameState): void {
    41→  const resources = state.resourceEconomy;
    42→  if (!resources) return; // Not initialized yet
    43→  
    44→  // Update in order of dependencies
    45→  updateFossilFuelDepletion(state, resources);
    46→  updateMetalDepletion(state, resources);
    47→  updateRenewableRegeneration(state, resources);
