    59→
    60→// ============================================================================
    61→// FOSSIL FUEL DEPLETION
    62→// ============================================================================
    63→
    64→function updateFossilFuelDepletion(state: GameState, resources: ResourceEconomy): void {
    65→  // Base depletion scales with economic stage
    66→  const economicStage = state.globalMetrics?.economicTransitionStage || 1;
    67→  const economicMultiplier = 0.5 + economicStage * 0.5; // 1.0x at stage 1, 2.5x at stage 3
    68→  
    69→  // Update each fossil fuel
    70→  updateFossilFuel(resources.oil, economicMultiplier, resources);
    71→  updateFossilFuel(resources.coal, economicMultiplier, resources);
    72→  updateFossilFuel(resources.naturalGas, economicMultiplier, resources);
    73→  
    74→  // Oil spills (random events)
    75→  if (resources.oil.reserves > 0 && Math.random() < resources.oil.spillRisk) {
    76→    resources.oil.spillSeverity = Math.random() * 0.3 + 0.1; // 10-40% severity
    77→    resources.ocean.pollutionLoad += resources.oil.spillSeverity * 0.05;
    78→    
    79→    addEvent(state, {
    80→      id: `oil_spill_${state.currentMonth}`,
    81→      timestamp: state.currentMonth,
    82→      type: 'crisis',
