    84→      title: '🛢️ Oil Spill',
    85→      description: `Major oil spill occurred. ${(resources.oil.spillSeverity * 100).toFixed(0)}% severity. Ocean pollution increasing.`,
    86→      effects: { ocean_pollution: resources.oil.spillSeverity }
    87→    });
    88→  }
    89→}
    90→
    91→function updateFossilFuel(
    92→  fuel: FossilFuelResource,
    93→  economicMultiplier: number,
    94→  resources: ResourceEconomy
    95→): void {
    96→  if (fuel.reserves <= 0) {
    97→    fuel.monthlyExtraction = 0;
    98→    fuel.monthlyConsumption = 0;
    99→    return;
   100→  }
   101→  
   102→  // Extraction scales with depletion rate, economic activity, and substitution
   103→  const substitutionFactor = 1 - fuel.substitutionLevel * 0.8; // Up to 80% reduction
   104→  fuel.monthlyExtraction = fuel.depletionRate * economicMultiplier * substitutionFactor;
   105→
   106→  // FIX #18 (Oct 22, 2025): Consumption responds to renewable energy deployment
   107→  // Research: IEA World Energy Outlook 2024, IPCC AR6 WG3 (2022)
   108→  // - Clean energy substitution reduces fossil fuel demand independently of extraction
   109→  // - Peak fossil fuel demand: 2025 (oil/coal), 2030 (gas) - IEA Net Zero Scenario
   110→  // - At 50% renewable penetration, fossil consumption drops ~60-70% (not 50%)
   111→  // - At 80% renewable, fossil consumption drops ~90-95% (grid optimization + storage)
   112→
   113→  const renewablePercentage = resources.energy.renewablePercentage;
   114→
   115→  // Consumption reduction from renewable substitution
   116→  // Accelerates faster than linear: grid optimization, storage, efficiency gains
   117→  // Formula: consumptionReduction = renewablePercentage ^ 0.9 (slightly sublinear)
   118→  // At 0% renewable → 0% reduction
   119→  // At 50% renewable → 46% reduction
   120→  // At 80% renewable → 76% reduction
   121→  // At 100% renewable → 100% reduction (but capped at 95% for baseline demand)
   122→  const consumptionReduction = Math.min(0.95, Math.pow(renewablePercentage, 0.9));
   123→
   124→  fuel.monthlyConsumption = fuel.monthlyExtraction * (1 - consumptionReduction);
   125→  
   126→  // Deplete reserves
   127→  fuel.reserves = Math.max(0, fuel.reserves - fuel.monthlyExtraction);
   128→  
   129→  // Extraction cost increases as reserves deplete (harder to extract)
   130→  const depletionFactor = fuel.reserves / fuel.initialReserves;
   131→  fuel.extractionCost = fuel.extractionCost * (1 + (1 - depletionFactor) * 0.05); // Up to 5% increase per month
   132→  
   133→  // Market price follows supply/demand
   134→  if (fuel.reserves < 0.3) {
   135→    fuel.marketPrice *= 1.02; // 2% price increase per month when scarce
   136→  }
   137→}
   138→
   139→// ============================================================================
   140→// METAL DEPLETION & RECYCLING
   141→// ============================================================================
   142→
   143→function updateMetalDepletion(state: GameState, resources: ResourceEconomy): void {
   144→  const economicStage = state.globalMetrics?.economicTransitionStage || 1;
   145→  const economicMultiplier = 0.5 + economicStage * 0.5;
   146→  
   147→  // Update each metal
   148→  updateMetal(resources.iron, economicMultiplier, resources);
   149→  updateMetal(resources.copper, economicMultiplier, resources);
   150→  updateMetal(resources.rareEarths, economicMultiplier, resources);
   151→  updateMetal(resources.lithium, economicMultiplier, resources);
   152→  
   153→  // Special: Copper and Rare Earths demand increases with clean energy transition
   154→  const renewablePercentage = resources.energy.renewablePercentage;
   155→  if (renewablePercentage > 0.3) {
   156→    // Clean energy needs 3x more copper, 5x more rare earths
   157→    const cleanEnergyDemand = (renewablePercentage - 0.3) * 2; // Peaks at +1.4x at 100% renewable
   158→    resources.copper.monthlyExtraction *= (1 + cleanEnergyDemand);
   159→    resources.rareEarths.monthlyExtraction *= (1 + cleanEnergyDemand * 1.5);
   160→  }
   161→  
   162→  // Special: Lithium demand increases with EVs
   163→  const oilSubstitution = resources.oil.substitutionLevel;
   164→  if (oilSubstitution > 0.1) {
   165→    // EVs need massive lithium
   166→    const evDemand = oilSubstitution * 5; // 5x multiplier
   167→    resources.lithium.monthlyExtraction *= (1 + evDemand);
   168→  }
   169→}
   170→
   171→function updateMetal(
   172→  metal: MetalResource,
   173→  economicMultiplier: number,
   174→  resources: ResourceEconomy
   175→): void {
   176→  // Virgin extraction
   177→  if (metal.reserves > 0) {
   178→    metal.monthlyExtraction = metal.depletionRate * economicMultiplier;
   179→    metal.reserves = Math.max(0, metal.reserves - metal.monthlyExtraction);
   180→    
   181→    // Extraction cost increases as depletes
   182→    const depletionFactor = metal.reserves / metal.initialReserves;
   183→    metal.extractionCost *= (1 + (1 - depletionFactor) * 0.03); // 3% per month
   184→  } else {
   185→    metal.monthlyExtraction = 0;
   186→  }
   187→  
   188→  // Recycling (from circular economy tech)
   189→  const circularEconomy = resources.circularityIndex; // Boosted by tech
   190→  metal.monthlyRecycling = metal.monthlyConsumption * metal.recyclingRate * circularEconomy;
   191→  metal.recycledStock = Math.min(1.0, metal.recycledStock + metal.monthlyRecycling * metal.recyclingEfficiency);
   192→  
   193→  // Total consumption (virgin + recycled)
   194→  const recycledContribution = metal.recycledStock * metal.recyclingRate;
   195→  metal.monthlyConsumption = metal.monthlyExtraction + recycledContribution;
   196→  
   197→  // Use up recycled stock
   198→  metal.recycledStock = Math.max(0, metal.recycledStock - recycledContribution);
   199→  
   200→  // Criticality increases as reserves deplete
   201→  if (metal.reserves < 0.4) {
   202→    metal.criticality = Math.min(1.0, metal.criticality + 0.01);
   203→  }
   204→}
   205→
   206→// ============================================================================
   207→// RENEWABLE RESOURCES
   208→// ============================================================================
   209→
   210→function updateRenewableRegeneration(state: GameState, resources: ResourceEconomy): void {
   211→  updateRenewable(resources.food, state, resources);
   212→  updateRenewable(resources.water, state, resources);
   213→  updateRenewable(resources.timber, state, resources);
   214→  
   215→  // Food-specific: Pollinators and soil health
   216→  const food = resources.food;
   217→  const biodiversity = state.environmentalAccumulation?.biodiversityIndex || 0.8;
   218→  
   219→  // Pollinators decline with biodiversity and pesticides
   220→  food.pollinatorPopulation = Math.max(0.1, biodiversity * 0.9); // Track biodiversity closely
   221→  
   222→  // Soil health degrades with monoculture, improves with sustainable ag
   223→  const soilDegradation = food.overharvest * 0.02; // Overharvest damages soil
   224→  food.soilHealth = Math.max(0.3, food.soilHealth - soilDegradation);
   225→  
   226→  // Climate stress from temperature
   227→  const tempAnomaly = resources.co2.temperatureAnomaly;
   228→  food.climateStress = Math.min(1.0, tempAnomaly / 4.0); // Maxes at +4°C
   229→  food.waterAvailability = Math.max(0.3, 1.0 - food.climateStress * 0.5); // Droughts
   230→  
   231→  // Regeneration multiplier reduced by stress
   232→  food.regenerationMultiplier = food.soilHealth * food.pollinatorPopulation * (1 - food.climateStress * 0.5);
   233→  
   234→  // Water-specific: Aquifer depletion and climate
   235→  const water = resources.water;
   236→  if (water.overharvest > 0) {
   237→    water.aquiferLevels = Math.max(0.1, water.aquiferLevels - water.overharvest * 0.5);
   238→  }
   239→  water.regenerationMultiplier = Math.max(0.5, 1.0 - resources.co2.temperatureAnomaly * 0.15); // Climate disrupts water cycle
   240→  
   241→  // Timber-specific: Old growth doesn't regenerate
   242→  const timber = resources.timber;
   243→  if (timber.monthlyHarvest > timber.sustainableHarvestRate) {
   244→    timber.oldGrowthRemaining = Math.max(0, timber.oldGrowthRemaining - 0.005);
   245→  }
   246→}
   247→
   248→function updateRenewable(
   249→  resource: FoodResource | WaterResource | TimberResource,
   250→  state: GameState,
   251→  resources: ResourceEconomy
   252→): void {
   253→  // Regeneration
   254→  const regen = resource.monthlyRegeneration * resource.regenerationMultiplier;
   255→  resource.reserves = Math.min(resource.capacity, resource.reserves + regen);
   256→  
   257→  // Harvesting (scales with economic stage)
   258→  const economicStage = state.globalMetrics?.economicTransitionStage || 1;
   259→  const economicMultiplier = 0.8 + economicStage * 0.2; // 1.0x to 1.4x
   260→  resource.monthlyHarvest = resource.sustainableHarvestRate * economicMultiplier;
   261→  
   262→  // Consume
   263→  resource.reserves = Math.max(0, resource.reserves - resource.monthlyHarvest);
   264→  
   265→  // Overharvest if consumption exceeds regeneration
   266→  resource.overharvest = Math.max(0, resource.monthlyHarvest - regen);
   267→  
   268→  // Sustainability index
   269→  if (regen > 0) {
   270→    resource.sustainabilityIndex = Math.min(1.0, resource.monthlyHarvest / regen);
   271→  } else {
   272→    resource.sustainabilityIndex = 0; // Collapse
   273→  }
   274→  
   275→  // Capacity degrades with persistent overharvest
   276→  if (resource.overharvest > resource.sustainableHarvestRate * 0.2) {
   277→    resource.capacity = Math.max(0.5, resource.capacity - 0.002); // 0.2% per month
   278→  }
   279→}
   280→
   281→// ============================================================================
   282→// ENERGY SYSTEM
   283→// ============================================================================
   284→
   285→function updateEnergySystem(state: GameState, resources: ResourceEconomy): void {
   286→  const energy = resources.energy;
   287→  
   288→  // Demand scales with economic stage
   289→  const economicStage = state.globalMetrics?.economicTransitionStage || 1;
   290→  energy.totalDemand = 95 + economicStage * 10; // 95 → 125 units
   291→  
   292→  // Production from each source (limited by capacity and fuel availability)
   293→  energy.sources.oil = Math.min(energy.capacity.oil, energy.sources.oil);
   294→  energy.sources.coal = Math.min(energy.capacity.coal, energy.sources.coal);
   295→  energy.sources.naturalGas = Math.min(energy.capacity.naturalGas, energy.sources.naturalGas);
   296→  
   297→  // Fossil sources decline as fuels deplete
   298→  if (resources.oil.reserves < 0.1) energy.sources.oil *= 0.9; // 10% reduction per month when nearly depleted
   299→  if (resources.coal.reserves < 0.1) energy.sources.coal *= 0.9;
   300→  if (resources.naturalGas.reserves < 0.1) energy.sources.naturalGas *= 0.9;
   301→  
   302→  // Renewables grow with clean energy tech (handled in tech deployment)
   303→  // Fusion unlocks when tech deployed (handled in tech deployment)
   304→  
   305→  // Total production
   306→  energy.totalProduction = 
   307→    energy.sources.oil +
   308→    energy.sources.coal +
   309→    energy.sources.naturalGas +
   310→    energy.sources.nuclear +
   311→    energy.sources.solar +
   312→    energy.sources.wind +
   313→    energy.sources.hydro +
   314→    energy.sources.fusion;
   315→  
   316→  // Surplus/deficit
   317→  energy.surplus = energy.totalProduction - energy.totalDemand;
   318→  
   319→  // Renewable percentage
   320→  energy.renewablePercentage = (
   321→    energy.sources.solar +
   322→    energy.sources.wind +
   323→    energy.sources.hydro +
   324→    energy.sources.fusion
   325→  ) / Math.max(1, energy.totalProduction);
   326→  
   327→  // Carbon intensity (kg CO2 per unit energy)
   328→  const fossilProduction = energy.sources.oil + energy.sources.coal + energy.sources.naturalGas;
   329→  const fossilCO2 = 
   330→    energy.sources.oil * resources.oil.co2PerUnit * 0.1 +
   331→    energy.sources.coal * resources.coal.co2PerUnit * 0.1 +
   332→    energy.sources.naturalGas * resources.naturalGas.co2PerUnit * 0.1;
   333→  energy.carbonIntensity = fossilCO2 / Math.max(1, energy.totalProduction);
   334→}
   335→
   336→// ============================================================================
   337→// CO2 & CLIMATE SYSTEM
   338→// ============================================================================
   339→
   340→function updateCO2System(state: GameState, resources: ResourceEconomy): void {
   341→  const co2 = resources.co2;
   342→  const energy = resources.energy;
   343→  
   344→  // === EMISSIONS FROM FOSSIL FUEL USE ===
   345→  
   346→  // Calculate emissions (Gt CO2 per month)
   347→  // Scale: 1 unit of monthly extraction ≈ 1% of global reserves ≈ 3 Gt CO2
   348→  const oilEmissions = resources.oil.monthlyConsumption * resources.oil.co2PerUnit * 3.0;
   349→  const coalEmissions = resources.coal.monthlyConsumption * resources.coal.co2PerUnit * 3.0;
   350→  const gasEmissions = resources.naturalGas.monthlyConsumption * resources.naturalGas.co2PerUnit * 3.0;
   351→  
   352→  // Methane leakage (CH4 is 80x worse than CO2 over 20 years)
   353→  const methaneEmissions = resources.naturalGas.monthlyConsumption * 
   354→    resources.naturalGas.methaneLeakage * 80;
   355→  
   356→  // Total monthly emissions (Gt CO2 equivalent)
   357→  const monthlyEmissions = oilEmissions + coalEmissions + gasEmissions + methaneEmissions;
   358→  co2.annualEmissions = monthlyEmissions * 12;
   359→  
   360→  // === ATMOSPHERIC CO2 ===
   361→  
   362→  // Natural sinks absorb some emissions (ocean + land)
   363→  const sinkCapacity = (co2.oceanAbsorption + co2.landAbsorption) * (1 - co2.sinkSaturation);
   364→  const netEmissions = Math.max(0, monthlyEmissions - sinkCapacity / 12);
   365→  
   366→  // Convert to ppm (2.13 Gt CO2 = 1 ppm)
   367→  const ppmIncrease = netEmissions / 2.13;
   368→  co2.atmosphericCO2 += ppmIncrease;
   369→  
   370→  // Track cumulative emissions (PERMANENT!)
   371→  co2.cumulativeEmissions += monthlyEmissions;
   372→  
   373→  // === SINKS SATURATE ===
   374→  
   375→  // Ocean absorption decreases with acidification
   376→  const ocean = resources.ocean;
   377→  if (ocean.pH < 8.0) {
   378→    const acidificationFactor = (8.0 - ocean.pH) / 0.5; // 0 to 1
   379→    co2.oceanAbsorption = Math.max(5, 10 * (1 - acidificationFactor * 0.5)); // Drops to 5 Gt/year
   380→  }
   381→  
   382→  // Land absorption decreases with deforestation
   383→  const forestLoss = 1 - resources.timber.forestCover;
   384→  co2.landAbsorption = Math.max(5, 11 * (1 - forestLoss * 0.3)); // Drops to 7.7 Gt/year
   385→  
   386→  // Sinks saturate with cumulative emissions
   387→  co2.sinkSaturation = Math.min(0.8, co2.cumulativeEmissions / 1000); // 80% saturated at 1000 Gt
   388→  
   389→  // === TEMPERATURE ===
   390→  
   391→  // IPCC formula: T = sensitivity * log2(CO2 / CO2_preindustrial)
   392→  const co2Ratio = co2.atmosphericCO2 / 280; // 280 ppm = pre-industrial
   393→  const co2Doublings = Math.log2(co2Ratio);
   394→  co2.temperatureAnomaly = co2Doublings * co2.climateSensitivity;
   395→  
   396→  // === TIPPING POINTS ===
   397→  
   398→  // Arctic ice loss accelerates above +1.5°C
   399→  if (co2.temperatureAnomaly > 1.5) {
   400→    const iceLossRate = (co2.temperatureAnomaly - 1.5) * 0.02; // 2% per °C per month
   401→    co2.arcticIceLoss = Math.min(1.0, co2.arcticIceLoss + iceLossRate);
   402→  }
   403→  
   404→  // Permafrost thaw (methane feedback)
   405→  if (co2.temperatureAnomaly > 2.0) {
   406→    const thawRate = (co2.temperatureAnomaly - 2.0) * 0.01;
   407→    co2.permafrostThaw = Math.min(1.0, co2.permafrostThaw + thawRate);
   408→    
   409→    // Methane feedback (permafrost releases CH4)
   410→    const methaneFeedback = co2.permafrostThaw * 0.5; // Up to 0.5 Gt CO2eq per month
   411→    co2.atmosphericCO2 += methaneFeedback / 2.13;
   412→  }
   413→  
   414→  // Amazon dieback (forest → savanna)
   415→  const amazonStress = co2.temperatureAnomaly * 0.05 + (1 - resources.water.reserves) * 0.1;
   416→  co2.amazonDieback = Math.min(1.0, co2.amazonDieback + amazonStress * 0.005);
   417→  
   418→  // Dieback reduces land carbon sink
   419→  if (co2.amazonDieback > 0.3) {
   420→    co2.landAbsorption *= (1 - co2.amazonDieback * 0.5);
   421→  }
   422→}
