   424→// ============================================================================
   425→// OCEAN HEALTH
   426→// ============================================================================
   427→
   428→function updateOceanHealth(state: GameState, resources: ResourceEconomy): void {
   429→  const ocean = resources.ocean;
   430→  const co2 = resources.co2;
   431→  
   432→  // === ACIDIFICATION (from atmospheric CO2) ===
   433→  
   434→  // CO2 dissolves in ocean, forms carbonic acid
   435→  const co2Above420 = Math.max(0, co2.atmosphericCO2 - 420); // ppm above baseline
   436→  ocean.acidification += co2Above420 * 0.00005; // Accumulates slowly
   437→  
   438→  // pH drops with acidification
   439→  ocean.pH = 8.2 - ocean.acidification * 0.5; // Starts at 8.2, drops to 7.7 at 100% acidification
   440→  
   441→  // === THERMAL STRESS (from warming) ===
   442→  
   443→  ocean.thermalStress = Math.min(1.0, co2.temperatureAnomaly / 4.0); // Maxes at +4°C
   444→  
   445→  // Thermal stress reduces oxygen capacity
   446→  const thermalOxygenLoss = ocean.thermalStress * 0.01; // 1% per month at max stress
   447→  ocean.oxygenLevel = Math.max(0, ocean.oxygenLevel - thermalOxygenLoss);
   448→  
   449→  // === POLLUTION (from mining, spills, plastics) ===
   450→  
   451→  // Mining runoff
   452→  const miningPollution = 
   453→    resources.lithium.monthlyExtraction * 0.02 +
   454→    resources.rareEarths.monthlyExtraction * 0.03 + // Worse (radioactive)
   455→    resources.copper.monthlyExtraction * 0.01;
   456→  ocean.pollutionLoad = Math.min(1.0, ocean.pollutionLoad + miningPollution);
   457→  
   458→  // Plastics (from oil)
   459→  const plasticsProduction = resources.oil.monthlyConsumption * resources.oil.plasticProduction;
   460→  ocean.plasticConcentration = Math.min(1.0, ocean.plasticConcentration + plasticsProduction * 0.005);
   461→  
   462→  // === PHYTOPLANKTON (pH kills them) ===
   463→  
   464→  if (ocean.pH < 7.9) {
   465→    const phytoDie = (7.9 - ocean.pH) * 0.5; // 50% loss per 0.1 pH drop
   466→    ocean.phytoplanktonPopulation *= (1 - phytoDie * 0.01); // 0.5% per month
   467→  }
   468→  
   469→  // Phytoplankton also affected by pollution
   470→  ocean.phytoplanktonPopulation *= (1 - ocean.pollutionLoad * 0.005);
   471→  
   472→  // === WHALE PUMP (Phase 2.9+) ===
   473→  // Research: Whales cycle nutrients (iron, nitrogen, phosphorus) from depth to surface
   474→  // This fertilizes phytoplankton, enhancing ocean productivity
   475→  // Source: "The Whale Pump" (Roman et al. 2010), WDC, NOAA, WWF
   476→  
   477→  const tech = state.breakthroughTech;
   478→  if (tech?.interspeciesComm?.deploymentLevel && tech.interspeciesComm.deploymentLevel > 0.5) {
   479→    // Understanding cetacean behavior → restore whale/dolphin populations → nutrient cycling
   480→    const deploymentLevel = tech.interspeciesComm.deploymentLevel;
   481→    
   482→    // WHALE PUMP EFFECT: Nutrient cycling boosts phytoplankton
   483→    // Research: Whales enhance primary productivity in regions where they occur in high densities
   484→    // Conservative estimate: 1-2% boost at full deployment (whales restore to ~50% of pre-whaling)
   485→    const whalePumpBoost = deploymentLevel * 0.015; // +1.5%/month at full deployment
   486→    ocean.phytoplanktonPopulation = Math.min(1.0, ocean.phytoplanktonPopulation + whalePumpBoost);
   487→    
   488→    // FISH ABUNDANCE: "Bigger fisheries where whales are dense" (research)
   489→    const fisheryBoost = deploymentLevel * 0.01; // +1%/month
   490→    ocean.fishStocks = Math.min(1.0, ocean.fishStocks + fisheryBoost);
   491→    
   492→    // DEAD ZONE REDUCTION: Nutrient distribution prevents anoxia
   493→    const deadZoneReduction = deploymentLevel * 0.008; // -0.8%/month
   494→    ocean.deadZoneExtent = Math.max(0, ocean.deadZoneExtent - deadZoneReduction);
   495→    
   496→    // Log annually
   497→    if (state.currentMonth % 12 === 0) {
   498→      console.log(`🐋 WHALE PUMP ACTIVE: Cetacean populations restored`);
   499→      console.log(`   Nutrient cycling: phytoplankton +${(whalePumpBoost * 100).toFixed(1)}%, fish +${(fisheryBoost * 100).toFixed(1)}%, dead zones -${(deadZoneReduction * 100).toFixed(1)}%`);
   500→    }
   501→  }
   502→  
   503→  // === OXYGEN (from phytoplankton) ===
   504→  
   505→  // 70% of ocean oxygen from phytoplankton, 30% from atmospheric exchange
   506→  const phytoContribution = ocean.phytoplanktonPopulation * 0.7;
   507→  const targetOxygen = phytoContribution + 0.3;
   508→  
   509→  // Oxygen adjusts slowly
   510→  const oxygenChange = (targetOxygen - ocean.oxygenLevel) * 0.1; // 10% adjustment per month
   511→  ocean.oxygenLevel = Math.max(0, Math.min(1.0, ocean.oxygenLevel + oxygenChange));
   512→  
   513→  // === DEAD ZONES (from low oxygen) ===
   514→  
   515→  if (ocean.oxygenLevel < 0.5) {
   516→    const deadZoneGrowth = (0.5 - ocean.oxygenLevel) * 0.05; // 5% per month
   517→    ocean.deadZoneExtent = Math.min(1.0, ocean.deadZoneExtent + deadZoneGrowth);
   518→  }
   519→  
   520→  // Pollution amplifies dead zones
   521→  ocean.deadZoneExtent *= (1 + ocean.pollutionLoad * 0.5);
   522→  ocean.deadZoneExtent = Math.min(1.0, ocean.deadZoneExtent);
   523→  
   524→  // === FISH STOCKS (ecosystem health) ===
   525→  
   526→  // Fish decline with acidification, oxygen loss, pollution
   527→  const fishDieoff = 
   528→    (ocean.pH < 7.8 ? 0.01 : 0) + // Acidification
   529→    (ocean.oxygenLevel < 0.6 ? 0.008 : 0) + // Oxygen
   530→    ocean.pollutionLoad * 0.005 + // Pollution
   531→    ocean.deadZoneExtent * 0.01; // Dead zones
   532→  
   533→  ocean.fishStocks = Math.max(0, ocean.fishStocks - fishDieoff);
   534→  
   535→  // Overfishing (economic pressure)
   536→  const economicStage = state.globalMetrics?.economicTransitionStage || 1;
   537→  let overfishing = economicStage * 0.003; // 0.3-0.9% per month
   538→  
   539→  // PUBLIC SUPPORT FOR OCEAN PROTECTION (from interspecies communication)
   540→  // When people can talk to whales/dolphins, they LOVE them and support ocean-friendly policies
   541→  // This reduces overfishing, creates marine protected areas, reduces pollution
   542→  if (tech?.interspeciesComm?.deploymentLevel && tech.interspeciesComm.deploymentLevel > 0.3) {
   543→    // Public support reduces overfishing by 30-90% (deployment-dependent)
   544→    const policyStrength = tech.interspeciesComm.deploymentLevel;
   545→    overfishing *= (1 - policyStrength * 0.9); // Up to 90% reduction
   546→    
   547→    // Also reduces pollution (public demands cleaner oceans)
   548→    const pollutionReduction = policyStrength * 0.005; // -0.5%/month at full deployment
   549→    ocean.pollutionLoad = Math.max(0, ocean.pollutionLoad - pollutionReduction);
   550→  }
   551→  
   552→  ocean.fishStocks = Math.max(0, ocean.fishStocks - overfishing);
   553→  
   554→  // === ECOSYSTEM RESILIENCE ===
   555→  
   556→  ocean.ecosystemResilience = (
   557→    ocean.phytoplanktonPopulation * 0.3 +
   558→    ocean.fishStocks * 0.2 +
   559→    (1 - ocean.pollutionLoad) * 0.2 +
   560→    (1 - ocean.deadZoneExtent) * 0.3
   561→  );
   562→  
   563→  // === ANOXIC RISK ===
   564→  
   565→  ocean.anoxicRisk = ocean.deadZoneExtent * 0.8 + (ocean.oxygenLevel < 0.3 ? 0.2 : 0);
   566→  
   567→  // === POINT OF NO RETURN ===
   568→  
   569→  ocean.recoveryPossible = (
   570→    ocean.pH > 7.5 &&
   571→    ocean.oxygenLevel > 0.2 &&
   572→    ocean.deadZoneExtent < 0.6 &&
   573→    ocean.phytoplanktonPopulation > 0.1
   574→  );
   575→  
   576→  // === CRISIS CHECK ===
   577→  
   578→  const wasInCrisis = ocean.inCrisis;
   579→  ocean.inCrisis = (
   580→    ocean.pH < 7.8 ||
   581→    ocean.oxygenLevel < 0.5 ||
   582→    ocean.deadZoneExtent > 0.3
   583→  );
   584→  
   585→  if (ocean.inCrisis) {
   586→    ocean.monthsInCrisis++;
   587→    
   588→    // First month of crisis
   589→    if (!wasInCrisis) {
   590→      addEvent(state, {
   591→        id: `ocean_crisis_${state.currentMonth}`,
   592→        timestamp: state.currentMonth,
   593→        type: 'crisis',
   594→        severity: 'critical',
   595→        title: '🌊 OCEAN CRISIS',
   596→        description: `Ocean health collapsing! pH: ${ocean.pH.toFixed(2)}, Oxygen: ${(ocean.oxygenLevel * 100).toFixed(0)}%, Dead zones: ${(ocean.deadZoneExtent * 100).toFixed(0)}%`,
   597→        effects: { ocean_crisis: 1.0 }
   598→      });
   599→    }
   600→  } else {
   601→    ocean.monthsInCrisis = 0;
   602→  }
   603→  
   604→  // === ANOXIC EXTINCTION EVENT ===
   605→  
   606→  if (!ocean.recoveryPossible && !ocean.geoengInterventionActive) {
   607→    // Past point of no return, trigger extinction
   608→    if (!state.extinctionState.active) {
   609→      state.extinctionState.active = true;
   610→      state.extinctionState.type = 'slow';
   611→      state.extinctionState.mechanism = 'anoxic_ocean';
   612→      state.extinctionState.severity = 1.0;
   613→      
   614→      addEvent(state, {
   615→        id: `anoxic_extinction_${state.currentMonth}`,
   616→        timestamp: state.currentMonth,
   617→        type: 'catastrophe',
   618→        severity: 'existential',
   619→        title: '☠️ ANOXIC OCEAN EXTINCTION',
   620→        description: `Oceans have passed the point of no return. pH: ${ocean.pH.toFixed(2)} (<7.5), oxygen: ${(ocean.oxygenLevel * 100).toFixed(0)}% (<20%). Phytoplankton populations collapsed. Atmospheric oxygen will decline over next 10-50 years. Human extinction inevitable without geoengineering intervention.`,
   621→        effects: { extinction: 1.0 }
   622→      });
   623→    }
   624→  }
   625→}
