   631→function updateIndustryOpposition(state: GameState, resources: ResourceEconomy): void {
   632→  const fossil = resources.fossilIndustry;
   633→  const mining = resources.miningIndustry;
   634→  const energy = resources.energy;
   635→  
   636→  // === FOSSIL FUEL INDUSTRY ===
   637→  
   638→  // Economic share tracks fossil fuel use
   639→  fossil.economicShare = (energy.sources.oil + energy.sources.coal + energy.sources.naturalGas) / 
   640→    Math.max(1, energy.totalProduction);
   641→  
   642→  // Political power correlates with economic share
   643→  fossil.politicalPower = fossil.economicShare * 0.9; // Slightly less than economic share
   644→  
   645→  // Desperation increases as reserves deplete and substitution grows
   646→  const avgFossilReserves = (resources.oil.reserves + resources.coal.reserves + resources.naturalGas.reserves) / 3;
   647→  const avgSubstitution = (resources.oil.substitutionLevel + resources.coal.substitutionLevel + resources.naturalGas.substitutionLevel) / 3;
   648→  
   649→  fossil.desperation = Math.max(0, 1 - avgFossilReserves / 0.5) * 0.5 + avgSubstitution * 0.5;
   650→  
   651→  // Opposition intensity scales with political power and desperation
   652→  fossil.researchResistance = fossil.politicalPower * fossil.desperation * 0.4; // Up to 40%
   653→  fossil.deploymentResistance = fossil.politicalPower * fossil.desperation * 0.5; // Up to 50%
   654→  
   655→  // Government capture (depends on government type)
   656→  const govType = state.government.type;
   657→  fossil.governmentCapture = (
   658→    (govType === 'authoritarian' && fossil.politicalPower > 0.6) ||
   659→    fossil.politicalPower > 0.75
   660→  );
   661→  
   662→  // Media disinformation scales with desperation
   663→  fossil.mediaDisinformation = fossil.desperation * 0.6;
   664→  
   665→  // Political donations
   666→  fossil.politicalDonations = fossil.economicShare * 25; // Up to $25B/year
   667→  
   668→  // Sabotage attempts (when desperate)
   669→  if (fossil.desperation > 0.7 && Math.random() < 0.01) {
   670→    fossil.sabotageAttempts++;
   671→    
   672→    addEvent(state, {
   673→      id: `fossil_sabotage_${state.currentMonth}`,
   674→      timestamp: state.currentMonth,
   675→      type: 'crisis',
   676→      severity: 'warning',
   677→      title: '⚠️ Industry Sabotage',
   678→      description: `Fossil fuel industry actors attempting to sabotage clean energy projects. Political opposition intensifying.`,
   679→      effects: { industry_opposition: 1.0 }
   680→    });
   681→  }
   682→  
   683→  // Industry collapse
   684→  if (fossil.economicShare < 0.1) {
   685→    fossil.collapsed = true;
   686→    fossil.politicalPower *= 0.5; // Rapid decline
   687→  }
   688→  
   689→  // === MINING INDUSTRY ===
   690→  
   691→  // Pivots to recycling as circular economy grows
   692→  mining.recyclingAdoption = resources.circularityIndex * 0.8;
   693→  
   694→  // Resistance declines as they pivot
   695→  mining.resistanceLevel = Math.max(0.1, 0.4 * (1 - mining.recyclingAdoption));
   696→  
   697→  // Political power moderate and stable
   698→  mining.politicalPower = 0.5 * (1 - mining.recyclingAdoption * 0.3);
   699→}
