   705→function updateAggregates(state: GameState, resources: ResourceEconomy): void {
   706→  // Import from resourceEconomy.ts
   707→  const { calculateResourceSecurity, identifyBottlenecks } = require('./resourceEconomy');
   708→  
   709→  // Total resource security (weighted average)
   710→  resources.totalResourceSecurity = calculateResourceSecurity(resources);
   711→  
   712→  // Energy independence (% renewable or domestic)
   713→  resources.energyIndependence = resources.energy.renewablePercentage;
   714→  
   715→  // Circularity index (% recycled) - boosted by tech
   716→  const avgRecyclingRate = (
   717→    resources.iron.recyclingRate +
   718→    resources.copper.recyclingRate +
   719→    resources.rareEarths.recyclingRate +
   720→    resources.lithium.recyclingRate
   721→  ) / 4;
   722→  resources.circularityIndex = avgRecyclingRate * 0.9; // Close to recycling rate
   723→  
   724→  // Fossil dependence
   725→  resources.fossilDependence = 1 - resources.energy.renewablePercentage;
   726→  
   727→  // Critical bottlenecks
   728→  resources.criticalBottlenecks = identifyBottlenecks(resources);
   729→  
   730→  // Legacy compatibility (for existing code using resourceReserves)
   731→  resources.resourceReserves = resources.totalResourceSecurity;
   732→  
   733→  // Update environmental accumulation for backward compatibility
   734→  if (state.environmentalAccumulation) {
   735→    state.environmentalAccumulation.resourceReserves = resources.totalResourceSecurity;
   736→  }
   737→}
