  maxMonths?: number;
  checkActualOutcomes?: boolean; // Stop when ACTUAL outcomes occur (not probabilities)
  onMonthEnd?: (state: GameState) => void; // Callback after each month
  logLevel?: LogLevel; // Override log level for this run

